// CSD_RATIONALE_BEGIN
// Tracks a single parser-valid working prefix `current` that is always kept equal
// to the returned `generated` prefix. On each step it inspects the number of valid
// next tokens: when the grammar frontier is narrow it uses fully constrained decoding,
// and when the frontier is wider it uses a softly constrained step that still checks
// whether the chosen token is grammar-valid. This state is sufficient for the task
// because the parser enforces the required structured output format, including the
// << >> arithmetic delimiters, while the loop only appends tokens that preserve a
// valid prefix and stops early on EOS or parser completion.
// CSD_RATIONALE_END
generated := currentPrefix;
var current := currentPrefix;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant parser.IsValidPrefix(current)
  invariant generated == current
  invariant exists suffix: Prefix :: current == currentPrefix + suffix
  invariant helpers.cost <= steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(current) {
    break;
  } else {
    var validCount := helpers.ValidTokenCount(parser, current);
    if validCount <= 4 {
      var next := helpers.ConstrainedStep(lm, parser, prompt, current, eosToken);
      if next == eosToken {
        break;
      } else {
        current := current + [next];
        generated := current;
        steps := steps + 1;
      }
    } else {
      var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, current, 3.0, eosToken);
      if next == eosToken {
        break;
      } else {
        if isValid {
          current := current + [next];
          generated := current;
          steps := steps + 1;
        } else {
          var repaired := helpers.RollbackToValidPrefix(parser, current);
          current := repaired;
          generated := repaired;
        }
      }
    }
  }
}
cost := helpers.cost;

